def maximum_gap(nums):
    if len(nums) < 2:
        return 0

    sorted_nums = sorted(nums)
    max_gap = 0
    for i in range(1, len(sorted_nums)):
        max_gap = max(max_gap, sorted_nums[i] - sorted_nums[i - 1])

    return max_gap


if __name__ == "__main__":
    print(maximum_gap([3, 6, 9, 1]))
    print(maximum_gap([10]))

